async function chargeCard(amount) {
  if (amount <= 0) throw new Error("Invalid amount");
  return gateway.charge(amount);
}

test("chargeCard rejects for invalid amount", async () => {
  try {
    await chargeCard(-5);
  } catch (err) {
    expect(err.message).toBe("Invalid amount");
  }
});

